import json
import numpy as np
from PIL import Image

specs = json.load(open("specs.json"))
sb = json.load(open("sb_means.json"))

info = {}
for name, d in specs.items():
    parts = d["spec"].split("|")
    best = None
    for p in parts[1:]:
        f = p.split("#")
        try:
            w, h, total, cols, rows, interval = map(int, f[:6])
        except ValueError:
            continue
        if best is None or w > best[0]:
            best = (w, h, total, interval)
    _, _, total, interval = best
    info[name] = {"total": total, "interval_s": interval/1000, "duration_s": total*interval/1000}
    print(f"{name}: {info[name]['duration_s']:.1f}s  ({total} tiles @ {interval/1000}s)")

img = Image.open("barcode.png").convert("RGB")
arr = np.asarray(img, dtype=np.float64)
B = arr[arr.shape[0]//2, :, :]

def pearson(a, b):
    a = a - a.mean(); b = b - b.mean()
    d = np.sqrt((a*a).sum() * (b*b).sum())
    return float((a*b).sum() / d) if d > 0 else 0.0

def build(name):
    d = sb[name]
    n = info[name]["total"]
    S = np.array(d["means"][:n], dtype=np.float64)
    dur = info[name]["duration_s"]
    t = (np.arange(n) + 0.5) * (dur / n)
    return t, S, dur

def interp(t, S, tq):
    return np.stack([np.interp(tq, t, S[:, c]) for c in range(3)], axis=1)

print("\n--- Hypothesis A: full duration -> 1000px ---")
resA = {}
for name in sorted(sb):
    t, S, dur = build(name)
    tq = (np.arange(1000) + 0.5) / 1000 * dur
    C = interp(t, S, tq)
    cors = [pearson(B[:, c], C[:, c]) for c in range(3)]
    corL = pearson(B.mean(axis=1), C.mean(axis=1))
    resA[name] = {"rgb_sum": sum(cors), "lum": corL, "rgb": cors}
    print(f"{name:14s} RGB {cors[0]:+.3f} {cors[1]:+.3f} {cors[2]:+.3f}   lum {corL:+.3f}   sum {sum(cors):+.3f}")

print("\n--- Hypothesis B: fixed seconds/px, best stretch ---")
resB = {}
for name in sorted(sb):
    t, S, dur = build(name)
    best = (-9, None)
    for s in np.arange(0.6, 3.51, 0.05):
        if 1000*s > dur: continue
        tq = np.arange(1000)*s + s/2
        C = interp(t, S, tq)
        corL = pearson(B.mean(axis=1), C.mean(axis=1))
        if corL > best[0]: best = (corL, s)
    resB[name] = best
    print(f"{name:14s} best lum {best[0]:+.3f} @ {best[1]:.2f}s/px  (dur {dur:.0f}s)")

json.dump({"A": resA, "B": resB}, open("scores.json", "w"), indent=1)
EOF
