import numpy as np

specs = json.load(open("specs.json"))

def level_groups(name):
    groups = []
    for p in specs[name]["spec"].split("|")[1:]:
        f = p.split("#")
        try:
            w, h, total, cols, rows, interval = map(int, f[:6])
        except ValueError:
            continue
        if f[6] == "default":
            continue
        groups.append(dict(w=w, h=h, total=total, cols=cols, rows=rows, interval=interval))
    return groups  # ordered smallest->largest

def parse_mhtml(path):
    msg = email.message_from_bytes(open(path, "rb").read(), policy=policy.default)
    imgs = []
    for part in msg.walk():
        if part.get_content_type().startswith("image/"):
            imgs.append(np.asarray(Image.open(io.BytesIO(part.get_payload(decode=True))).convert("RGB"), dtype=np.float64))
    return imgs

def slice_mosaics(imgs, tw, th, cols, rows):
    means = []
    for arr in imgs:
        H, W, _ = arr.shape
        for r in range(H // th):
            for c in range(min(cols, W // tw)):
                means.append(arr[r*th:(r+1)*th, c*tw:(c+1)*tw].mean(axis=(0,1)))
    return means

out = {}
for name in specs:
    path = {"A_uptown":"OPf0YbXqDm0","B_wdym":"DK_0jXPuIr0","C_attention":"nfs8NYg7yQM",
            "D_newrules":"k2qgadSvNyU","E_twil":"PMivT7MJ41M","F_sorry":"fRh_vgS2dFE",
            "G_baby":"kffacxfA7G4","H_counting":"hT_nvWreIhg","I_onthefloor":"t4H_Zoh7G5A",
            "J_perfect":"2Vv-BfVoq4g"}[name]
    imgs = parse_mhtml(f"sb/sb_{path}.mhtml")
    groups = level_groups(name)
    best = None
    for g in groups:
        # tile dims implied by image size: tw = W//cols
        W, H = imgs[0].shape[1], imgs[0].shape[0]
        tw, th = W // g["cols"], H // (g["rows"] if H % g["rows"] == 0 else None) if False else None, None
    # simpler: try each group with th from group spec
    for g in groups:
        tw = imgs[0].shape[1] // g["cols"]
        th = g["h"]
        if imgs[0].shape[0] % th != 0:
            continue
        means = slice_mosaics(imgs, tw, th, g["cols"], g["rows"])
        n = len(means)
        # count must be >= group's total and not wildly over (padded last mosaic ok)
        if g["total"] <= n <= g["total"] + g["cols"]*g["rows"]:
            cand = (g["w"], means[:g["total"]], g["interval"], g["total"])
            if best is None or cand[0] > best[0]:
                best = cand
    if best is None:
        print(f"{name}: NO MATCH"); continue
    _, means, interval, total = best
    out[name] = {"means": [list(map(float, m)) for m in means], "interval_s": interval/1000, "total": total,
                 "duration_s": total*interval/1000}
    print(f"{name}: {total} tiles @ {interval/1000}s = {total*interval/1000:.0f}s  (first {means[0].round(0)}, last {means[-1].round(0)})")

json.dump(out, open("sb_means2.json", "w"))
